function paintWaitingNext(){optionBoards=[];optionBoard=null;paintGrid({label:'Waiting for next signal',sides:[],gridError:'Waiting for next signal. Signal bante hi usi price se strike select hokar naya trade lagega.',price:null});const title=$('gridTitle');if(title)title.textContent='Waiting for next signal';const status=$('optionPreviewStatus');if(status){status.textContent='Waiting for next signal';for(const id of ['optionPreviewContract','optionPreviewSpot','optionPreviewPrice','optionPreviewExpiry']){const el=$(id);if(el)el.textContent='—';}const note=$('optionPreviewNote');if(note)note.textContent='Abhi koi strike select nahi hai. Signal bante hi naya strike aur trade lagega.';}const form=$('settingsForm');const sel=form?.optionDepth;if(sel)sel.replaceChildren(new Option('Waiting for next signal','1'));const sn=$('strikeChoicesNote');if(sn)sn.textContent='Next signal aane par strike usi price se select hoga.';syncOptionChartPicker();showOptionChartMessage('Waiting for next signal');}
function paintSignalBanner(){const title=$('signalBannerTitle');const detail=$('signalBannerDetail');if(!title)return;const s=state;const live=(s?.status==='running'?s.tradeMode:tradeChoice)==='live';const signal=s?.signal;if(s?.status==='running'&&!live){title.textContent='Started with current signal';if(detail)detail.textContent=s.option?.label?`${s.option.label} stays in this trade.`:'The selected option stays in this trade.';}else if(s?.status==='running'&&live&&!(signal?.spot>0)){title.textContent='Waiting for next signal';if(detail)detail.textContent='Upcoming signal will be detected, then the new trade is placed.';}else if(s?.status==='running'&&live&&signal?.spot>0){title.textContent='Signal detected';if(detail)detail.textContent=`${String(signal.side||'BUY').toUpperCase()} ${num(signal.spot)} · the new trade is placed from this signal.`;}else if(live){title.textContent='Upcoming signal';if(detail)detail.textContent='After start, the next buy or sell signal opens the new trade.';}else{title.textContent='Current signal';if(detail)detail.textContent=optionBoard?.label?`Last signal strike · ${optionBoard.label}${optionBoard.spot>0?' · signal '+num(optionBoard.spot):''}`:'Start uses the option already selected.';}}
