function setLoader(on,text){const el=$('appLoader');if(!el)return;el.hidden=!on;if(text&&$('loaderText'))$('loaderText').textContent=text;}
function showChartMessage(message){const el=$('emptyChart');el.style.display='grid';el.innerHTML=`<span class="spinner"></span><span>${escape(message)}</span>`;}
function istStamp(time){const seconds=typeof time==='number'?time:Math.floor(Date.UTC(time.year,time.month-1,time.day)/1000);return new Date(seconds*1000).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});}
function barChange(bar){const index=chartBars.findIndex(item=>item.time===bar.time);const full=index>=0?chartBars[index]:bar;const prev=index>0?chartBars[index-1]:null;const base=prev?prev.close:Number(full.open);const change=Number(full.close)-base;return {full,change,pct:base?(change/base)*100:0};}
function paintMove(change,pct,element){element.textContent=`${change>=0?'+':''}${num(change)} (${change>=0?'+':''}${pct.toFixed(2)}%)`;element.className=change>=0?'up':'down';}
function paintBar(bar){if(!bar)return;const {full,change,pct}=barChange(bar);$('barOpen').textContent=num(full.open);$('barHigh').textContent=num(full.high);$('barLow').textContent=num(full.low);$('barClose').textContent=num(full.close);$('barClose').className=full.close>=full.open?'up':'down';$('barVolume').textContent=full.volume==null?'—':Number(full.volume).toLocaleString('en-IN');paintMove(change,pct,$('barChange'));$('emaCloseValue').textContent=full.emaClose==null?'—':num(full.emaClose);$('emaOpenValue').textContent=full.emaOpen==null?'—':num(full.emaOpen);$('barTime').textContent=istStamp(full.time);}
function paintHeader(bar){if(!bar)return;$('lastPrice').textContent=num(bar.close);paintMove(barChange(bar).change,barChange(bar).pct,$('priceChange'));$('priceChange').classList.add('chg');}
function emaValues(candles,length,pick){const k=2/(length+1);let ema=null;const out=new Array(candles.length).fill(null);candles.forEach((candle,index)=>{if(index<length-1)return;if(ema===null){let sum=0;for(let offset=0;offset<length;offset++)sum+=pick(candles[index-offset]);ema=sum/length;}else ema=pick(candle)*k+ema*(1-k);out[index]=Math.round(ema*100)/100;});return out;}
function refreshBarAverages(candles){const last=candles.at(-1);if(!last)return;const periods=emaPeriods();last.emaOpen=emaValues(candles,periods.open,c=>c.open).at(-1);last.emaClose=emaValues(candles,periods.close,c=>c.close).at(-1);}
function emaPeriods(){const open=Math.trunc(Number(state?.config?.emaOpenPeriod))||5,close=Math.trunc(Number(state?.config?.emaClosePeriod))||6;return {open,close};}
function paintEmaLabels(){const {open,close}=emaPeriods();const set=(id,text)=>{const el=$(id);if(el&&el.textContent!==text)el.textContent=text;};set('emaOpenLabel',`${open} EMA Open`);set('emaCloseLabel',`${close} EMA Close`);set('emaOpenLegend',`${open} EMA · Open`);set('emaCloseLegend',`${close} EMA · Close`);emaOpenSeries?.applyOptions({title:`${open} EMA Open`});emaCloseSeries?.applyOptions({title:`${close} EMA Close`});}
let chartInterval='15minute';
let chartFrameManual=false,lastSignalFrame='';
function syncChartFrame(){const wanted=state?.config?.signalInterval||'15minute';if(wanted!==lastSignalFrame){lastSignalFrame=wanted;chartFrameManual=false;}if(chartFrameManual||wanted===chartInterval)return;chartInterval=wanted;document.querySelectorAll('#chartFrames button').forEach(b=>b.classList.toggle('selected',b.dataset.interval===wanted));}
function chartMinutes(){return ({'1minute':1,'3minute':3,'5minute':5,'15minute':15,'30minute':30,'60minute':60})[chartInterval]||15;}
function signalMinutes(){return ({'1minute':1,'3minute':3,'5minute':5,'15minute':15,'30minute':30,'60minute':60})[state?.config?.signalInterval]||15;}
function optionChartMinutes(){return ({'1minute':1,'5minute':5,'15minute':15,'30minute':30,'60minute':60})[optionChartInterval]||15;}
function istSessionBucket(ms,minutes){const day=istDay(ms/1000);const start=Date.parse(`${day}T09:15:00+05:30`);return Math.floor((start+Math.max(0,Math.floor((ms-start)/(minutes*60000)))*minutes*60000)/1000);}
function istBucket(ms, minutes=15){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(ms));const get=type=>parts.find(part=>part.type===type)?.value;const hour=get('hour')==='24'?'00':get('hour');const size=minutes>0?minutes:15;const minute=String(Math.floor(Number(get('minute'))/size)*size).padStart(2,'0');return Math.floor(Date.parse(`${get('year')}-${get('month')}-${get('day')}T${hour}:${minute}:00+05:30`)/1000);}
function paintLiveCandle(price){const live=Number(price);if(!(live>0)||!candleSeries||!chartBars.length)return;const previous=Number(chartBars.at(-1).close);if(previous>0&&(live<previous*0.5||live>previous*2))return;const minutes=chartMinutes();const bucket=istBucket(Date.now(), minutes);let bar=chartBars.at(-1);let added=false;if(istBucket(bar.time*1000, minutes)<bucket){const minute=istMinutes(Date.now()/1000);if(minute<9*60+15||minute>=15*60+30)return;const time=Math.max(bucket,Number(bar.time)+60);bar={time,open:live,high:live,low:live,close:live,volume:null,emaClose:null,emaOpen:null};chartBars.push(bar);added=true;}else{bar.close=live;bar.high=Math.max(bar.high,live);bar.low=Math.min(bar.low,live);}refreshBarAverages(chartBars);candleSeries.update({time:bar.time,open:bar.open,high:bar.high,low:bar.low,close:bar.close});if(bar.emaClose!=null)emaCloseSeries.update({time:bar.time,value:bar.emaClose});if(bar.emaOpen!=null)emaOpenSeries.update({time:bar.time,value:bar.emaOpen});if(added)paintSignals(chartBars);paintHeader(bar);if(added||!liveShown)showLatest();}
let chartFollow=true,liveShown=false;
function showLatest(count=56){const scale=tvChart?.timeScale();if(!scale||!chartBars.length||!chartFollow)return;const to=chartBars.length+3;scale.setVisibleLogicalRange({from:Math.max(0,to-count),to});liveShown=true;}
function watchChartFollow(){if(!tvChart||tvChart.__follow)return;tvChart.__follow=true;tvChart.timeScale().subscribeVisibleLogicalRangeChange(range=>{if(!range||!chartBars.length)return;chartFollow=range.to>=chartBars.length-1;});}
function showOptionLatest(count=48){const scale=optionChart?.timeScale();if(!scale||!optionBars.length)return;const to=optionBars.length+3;scale.setVisibleLogicalRange({from:Math.max(0,to-count),to});}
function paintOptionLive(price){const live=Number(price);if(!(live>0)||!optionSeries||!optionBars.length)return;const minute=istMinutes(Date.now()/1000);if(minute<9*60+15||minute>=15*60+30)return;const previous=Number(optionBars.at(-1).close);if(previous>0&&previous<3000&&live>8000)return;const bucket=istSessionBucket(Date.now(),optionChartMinutes());let bar=optionBars.at(-1),optionBarAdded=false;if(bar.time<bucket){if(previous>0&&(live<previous*0.2||live>previous*8))return;bar={time:Math.max(bucket,Number(bar.time)+60),open:live,high:live,low:live,close:live,volume:null};optionBars.push(bar);optionBarAdded=true;}else{if(previous>0&&(live<previous*0.5||live>previous*2))return;bar.close=live;bar.high=Math.max(bar.high,live);bar.low=Math.min(bar.low,live);}optionSeries.update({time:bar.time,open:bar.open,high:bar.high,low:bar.low,close:bar.close});if(optionBarAdded)showOptionLatest();}
function istDay(time){const ms=time>1e12?time:time*1000;return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(ms));}
function istMinutes(time){const ms=time>1e12?time:time*1000;const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(ms));const hour=parts.find(part=>part.type==='hour')?.value;const minute=parts.find(part=>part.type==='minute')?.value;return (hour==='24'?0:Number(hour))*60+Number(minute);}
function clockMinutes(value){const match=String(value||'').match(/^(\d{2}):(\d{2})/);return match?Number(match[1])*60+Number(match[2]):null;}
