function signalPrice(kind){const candles=chartBars;if(!candles?.length)return marketLast;const start=clockMinutes(state?.config?.strategyStart)??9*60+15;const end=clockMinutes(state?.config?.strategyEnd)??15*60+15;const today=istDay(Date.now()/1000);let level=null;for(let index=0;index<candles.length;index++){const candle=candles[index];if(istDay(candle.time)!==today)continue;const minute=istMinutes(candle.time);if(minute<start||minute>=end)continue;if(level&&(kind==='sell'?candle.low<level.low:candle.high>level.high))return kind==='sell'?level.low:level.high;const closed=index<candles.length-1||Date.now()>=(candle.time>1e12?candle.time:candle.time*1000)+signalMinutes()*60*1000;if(!closed||candle.emaClose==null||candle.emaOpen==null)continue;if(kind==='sell'&&candle.close<candle.open&&candle.close<candle.emaClose&&candle.close<candle.emaOpen)level={low:candle.low};if(kind!=='sell'&&candle.close>candle.open&&candle.close>candle.emaClose&&candle.close>candle.emaOpen)level={high:candle.high};}if(level)return kind==='sell'?level.low:level.high;return marketLast;}
