  $('gridBody').onclick=onGridClick;$('extraGrids').onclick=onGridClick;if($('brokerPositionsBody'))$('brokerPositionsBody').onclick=event=>{const button=event.target.closest('button[data-close-scrip]');if(button)closeBrokerPosition(button);};
